def find_solution(a, b, n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        r0, r1 = x, y
        u0, u1 = 1, 0
        v0, v1 = 0, 1
        while r1:
            r0, r1 = r1, r0 % r1
            u0, u1 = u1, u0 - (r0 // r1) * u1
            v0, v1 = v1, v0 - (r0 // r1) * v1
        return r0, u0, v0

    g, x, y = extended_gcd(a, b)
    if n % g:
        return None
    else:
        x *= n // g
        y *= n // g
        return (x, y)
