    mod_0, mod_1, mod_2 = 0, 0, 0

    # Counting the number of elements in each modulo 3 category
    for num in a:
        if num % 3 == 0:
            mod_0 += 1
        elif num % 3 == 1:
            mod_1 += 1
        else:  # num % 3 == 2
            mod_2 += 1

    # Using combinatorial approach to count the valid triples
    total_triples = 0
    for i in range(mod_0):
        for j in range(i + 1, mod_0):
            k = 2 * i + j + 1
            if k < mod_0:
                total_triples += mod_0 - k

    # Adjusting for the remaining elements in mod_1 and mod_2
    total_triples += mod_1 * (mod_1 - 1) // 2 + mod_2 * (mod_2 - 1) // 2

    return total_triples
