import heapq

def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    numbers.sort()
    min_heap = []
    for num in numbers:
        if min_heap and num - min_heap[0][0] < 0.01:
            heapq.heappush(min_heap, (num - numbers[0], num))
    smallest_diff, closest_num = heapq.heappop(min_heap)
    closest_pair = (numbers[0], numbers[-1])
    if closest_pair[0] - closest_pair[1] > smallest_diff:
        closest_pair = (min_heap[0][1], numbers[-1])
    return closest_pair

