        if not arr1:
            return arr2[k]
        if not arr2:
            return arr1[k]
        if k == 0:
            return min(arr1[0], arr2[0])
        m, n = len(arr1), len(arr2)
        i, j = min(k//2, m-1), min(k//2, n-1)
        if arr1[i] < arr2[j]:
            return find_kth(arr1[i+1:], arr2, k-i-1)
        else:
            return find_kth(arr1, arr2[j+1:], k-j-1)

    total_elements = n * 2
    if total_elements % 2 == 1:
        return find_kth(arr1, arr2, total_elements // 2)
    else:
        return (find_kth(arr1, arr2, total_elements // 2 - 1) + find_kth(arr1, arr2, total_elements // 2)) / 2
