def maxAverageOfPath(cost):
    N = len(cost)

    # Initialize DP table
    dp = [[[[0] * 3 for _ in range(N)] for _ in range(N)] for _ in range(N)]

    def dfs(x, y, state):
        if x == N - 1 and y == N - 1:
            return cost[x][y] / (N - 1)

        if dp[x][y][state] != 0:
            return dp[x][y][state]

        if state == 0:  # not visited yet
            avg = 0
            for dx, dy in [(0, 1), (1, 0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N:
                    avg += dfs(nx, ny, 1)
            dp[x][y][state] = avg / (N - 1 - x + N - 1 - y)
            return dp[x][y][state]

        # Already visited
        return cost[x][y] / (N - 1 - x + N - 1 - y)

    return dfs(0, 0, 0)
