def max_sum_increasing_subseq(a, n, index, k):
    # Initialize the dp array where dp[i][j] represents the maximum sum of increasing subsequence ending at i with prefix j
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    # Initialize the prefix sum array
    prefix_sum = [0] * (n + 1)

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            # Calculate the maximum sum including the kth element after i
            if j == k or i < k < j:
                prefix_sum[j] = max(prefix_sum[j], a[i] + dp[i + 1][j])
                dp[i][j] = max(prefix_sum[j], dp[i + 1][j])
            else:
                dp[i][j] = max(dp[i + 1][j], prefix_sum[j])

    # Return the maximum sum including the kth element
    return max(prefix_sum[k], dp[0][k])
