def lcs_of_three(X, Y, Z):
    m = len(X)
    n = len(Y)
    o = len(Z)

    # Create a 3D array to store lengths of longest common subsequence
    dp = [[[0 for k in range(o+1)] for j in range(n+1)] for i in range(m+1)]

    # Build the dp array from bottom up
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(1, o+1):
                if X[i-1] == Y[j-1] == Z[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # The length of the longest common subsequence is in dp[m][n][o]
    return dp[m][n][o]
```

