def pancake_sort(nums):
    def flip(nums, k):
        for i in range(k // 2):
            nums[i], nums[k - i - 1] = nums[k - i - 1], nums[i]

    n = len(nums)
    for size in range(n, 1, -1):
        mx_idx = nums.index(size)
        if mx_idx != size - 1:
            if mx_idx != 0:
                flip(nums, mx_idx + 1)
            flip(nums, size)
    return nums
