def min_Jumps(steps, d):
    # Base case: if d is 0, no jumps are needed
    if d == 0:
        return 0
    # If d is negative, it's not reachable from the origin
    if d < 0:
        return -1

    # Recursive helper function to find the minimum number of jumps
    def jumps_to_target(x, y, remaining_steps, previous_steps):
        # Base case: if all steps are used and target is not reached, return -1
        if remaining_steps == 0:
            return -1
        # Base case: if target is reached
        if x == 0 and y == 0:
            return previous_steps

        # Recursive case: explore all possible jumps
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            next_x, next_y = x + dx * steps, y + dy * steps
            next_steps = jumps_to_target(next_x, next_y, remaining_steps - 1, previous_steps + 1)
            if next_steps != -1:
                return next_steps
        # If no solution found in this step, return -1
        return -1

    # Start the recursion with the origin (0, 0) and initial steps remaining
    return jumps_to_target(d, 0, steps, 1)
