def comb_sort(nums):
    def generate_shuffled_list(nums):
        length = len(nums)
        shuffled = list(range(length))
        for i in range(length):
            shuffled[i] = nums[i]
        return shuffled

    def swap(nums, i, j):
        nums[i], nums[j] = nums[j], nums[i]

    def comb_sort(nums):
        if len(nums) <= 1:
            return
        gap = len(nums)
        is_sorted = False
        shrink_factor = 1.3
        while not is_sorted:
            gap = int(gap / shrink_factor)
            if gap > 1:
                is_sorted = False
            else:
                is_sorted = True
                gap = 1
            i = 0
            while i + gap < len(nums):
                if nums[i] > nums[i + gap]:
                    swap(nums, i, i + gap)
                    is_sorted = False
                i += 1

    def partition(nums, low, high):
        pivot = nums[high]
        i = low - 1
        for j in range(low, high):
            if nums[j] <= pivot:
                i += 1
                nums[i], nums[j] = nums[j], nums[i]
        nums[i + 1], nums[high] = nums[high], nums[i + 1]
        return i + 1

    def quicksort(nums, low, high):
        if len(nums) == 1:
            return
        if low < high:
