def count_rotation(arr):
    n = len(arr)
    if n == 0:
        return 0

    low, high = 0, n - 1

    while low <= high:
        if arr[low] <= arr[high]:
            return low

        mid = (low + high) // 2
        next = (mid + 1) % n
        prev = (mid - 1 + n) % n

        if arr[mid] <= arr[next] and arr[mid] <= arr[prev]:
            return mid

        elif arr[mid] <= arr[high]:
            high = mid - 1

        else:
            low = mid + 1

    return 0
