import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def neighbors(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield (nx, ny)

    def dijkstra(start):
        visited = set()
        heap = [(grid[start[0]][start[1]], start, (start,))]
        while heap:
            cost, pos, path = heapq.heappop(heap)
            if pos not in visited:
                if len(path) == k:
                    return path
                visited.add(pos)
                for nx, ny in neighbors(*pos):
                    if (grid[nx][ny], path) not in visited:
                        heapq.heappush(heap, (cost + grid[nx][ny], (nx, ny), path + ((nx, ny),)))

    return dijkstra((0, 0))
