def comb_sort(nums):
    def get_bubble_gap(nums):
        gap = len(nums)
        # Shrink gap by sorting factor (1.3)
        while gap >= 1:
            gap = int(gap / 1.3)
            if gap < 1:
                gap = 1
        return gap

    sorted = False
    gap = len(nums)
    shrink = 1.3

    while not sorted:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
            sorted = True
        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted = False

    return nums
