        return 0

    # Initialize the DP array
    dp = [0] * n
    dp[0] = a[0]

    # Fill the DP array
    for i in range(1, n):
        dp[i] = a[i]
        for j in range(i):
            if a[i] > a[j] and dp[i] < dp[j] + a[i]:
                dp[i] = dp[j] + a[i]

    # Find the maximum sum subsequence including the kth element
    max_sum = 0
    for i in range(index + 1, k + 1):
        max_sum = max(max_sum, dp[i])

    for i in range(k + 1, n):
        max_sum = max(max_sum, dp[i])

    return max_sum
