def exchange(lst1, lst2):
    even_lst1 = [num for num in lst1 if num % 2 == 0]
    odd_lst1 = [num for num in lst1 if num % 2 != 0]
    even_lst2 = [num for num in lst2 if num % 2 == 0]
    odd_lst2 = [num for num in lst2 if num % 2 != 0]

    if not odd_lst1:
        return "YES"
    if not even_lst2:
        return "NO"

    for num in even_lst2:
        if num in odd_lst1:
            odd_lst1.remove(num)
            even_lst2.remove(num)
            even_lst1.extend([num] * len(odd_lst1))
            odd_lst2.extend(odd_lst1)
            odd_lst1.clear()
            break
    else:
        return "NO"

    if not odd_lst1:
        return "YES"
    else:
        return "NO"

# Test cases
