def get_median(arr1, arr2, n):
    def find_kth_element(A, B, k):
        if not A:
            return B[k]
        if not B:
            return A[k]
        if k == 0:
            return min(A[0], B[0])
        ia, ib = len(A) - 1, len(B) - 1
        ma, mb = A[ia], B[ib]
        if ma <= mb:
            return find_kth_element(A[:ia], B[ib+1:], k-1)
        return find_kth_element(A[ia+1:], B[:ib], k-1)

    median = (find_kth_element(arr1, arr2, n//2) + find_kth_element(arr1, arr2, n//2 + 1)) / 2
    return median
