def get_Inv_Count(arr):
    def merge_count(arr, temp_arr, left, right):
        i = left  # starting index of left sub array
        j = right  # starting index of right sub array
        inv_count = 0
        k = left  # starting index of temp sub array
        while i <= j:
            if (arr[i] <= arr[j]):
                temp_arr[k] = arr[i]
                i += 1
            else:
                temp_arr[k] = arr[j]
                inv_count += (j - i)
                j -= 1
            k += 1
        return inv_count

    def merge_sort(arr, temp_arr, left, right):
        inv_count = 0
        if (right > left):
            mid = (right + left) // 2
            inv_count += merge_sort(arr, temp_arr, left, mid)
            inv_count += merge_sort(arr, temp_arr, mid + 1, right)
            inv_count += merge_count(arr, temp_arr, left, right)
        return inv_count

    return merge_sort(arr, [0] * len(arr), 0, len(arr) - 1)

