def max_sum_increasing_subseq(a, n, index, k):
    if index >= n or k >= n:
        return 0

    dp = [0] * n
    dp[0] = a[0]

    for i in range(1, n):
        dp[i] = a[i]
        for j in range(i):
            if a[i] > a[j]:
                dp[i] = max(dp[i], dp[j] + a[i])

    max_sum = dp[index]

    for i in range(index + 1, k + 1):
        max_sum = max(max_sum, dp[i])

    return max_sum
