def lcs_of_three(X, Y, Z):
    m = len(X)
    n = len(Y)
    p = len(Z)

    # Create a 3D list to store the lengths of LCS
    dp = [[[0 for i in range(p+1)] for j in range(n+1)] for k in range(m+1)]

    # Fill dp[][][] in bottom-up manner
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(1, p+1):
                if X[i-1] == Y[j-1] == Z[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # The length of the LCS
    index = dp[m][n][p]

    # Create a string to store the LCS
    lcs = [''] * (index + 1)
    lcs[index] = None

    # Start from the end of the strings and build the LCS from the dp array
    i, j, k = m, n, p
    while i > 0 and j > 0 and k > 0:
        if X[i-1] == Y[j-1] == Z[k-1]:
