def count_binary_seq(n):
    if n == 0:
        return 1
    if n == 1:
        return 2

    # Initialize a DP table
    dp = [[0] * (2*n+1) for _ in range(2*n+1)]
    for i in range(2*n+1):
        dp[i][i] = 2  # Base case: two sequences with single bit

    for length in range(2, 2*n+1, 2):
        for start in range(2*n - length + 1):
            end = start + length
            for i in range(start+1, end):
                dp[start][end] += dp[start][i] * dp[i+1][end]
                dp[start][end] %= 1000000007

    return dp[0][2*n]

