def comb_sort(nums):
    def swap(i, j):
        nums[i], nums[j] = nums[j], nums[i]

    n = len(nums)
    gap = n
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap > 1:
            sorted = False
        else:
            gap = 1
            sorted = True

        i = 0
        while i + gap < n:
            if nums[i] > nums[i + gap]:
                swap(i, i + gap)
                sorted = False
            i += 1
