def is_octagonal(n):
    # The nth octagonal number can be calculated using the formula: n * (3 * n - 2)
    # This function returns True if n is an octagonal number, False otherwise.
    def is_octagonal_number(k):
        # Solving the quadratic equation n^2 - n - (2k+1) = 0 for n
        a, b, c = 1, -1, -(2 * k + 1)
        discriminant = b**2 - 4 * a * c
        if discriminant < 0:
            return False
        else:
            n1 = (-b + discriminant**0.5) / (2 * a)
            n2 = (-b - discriminant**0.5) / (2 * a)
            return n1.is_integer() or n2.is_integer()

    return is_octagonal_number(n)
