from typing import List

def maxAverageOfPath(cost: List[List[int]]) -> float:
    n = len(cost)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = cost[0][0]

    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + cost[i][0]
        dp[0][i] = dp[0][i-1] + cost[0][i]

    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    max_avg = dp[n-1][n-1] / (n * n)
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0:
                max_avg = max(max_avg, (dp[i-1][j] + cost[i][j] * (n*n - (i + j - 1))) / (n * n - (i + j - 1)))
                max_avg = max(max_avg, (dp[i][j-1] + cost[i][j] * (n*n - (i + j - 1))) / (n * n - (i + j - 1)))
            elif i > 0:
                max_avg = max(max_avg, (dp[i-1][j] + cost[i][j] * (n*n - (i + j - 1))) / (n * n - (i + j - 1)))
            else:
                max_avg = max(max_avg, (dp[i][j-1] + cost[i][j] * (n*n - (i + j - 1))) / (n * n - (i + j - 1)))

    return max_avg

# Tests
