def get_median(arr1, arr2, n):
    def merge_sorted_lists(arr1, arr2):
        merged = []
        i, j = 0, 0
        while i < n and j < n:
            if arr1[i] < arr2[j]:
                merged.append(arr1[i])
                i += 1
            else:
                merged.append(arr2[j])
                j += 1
        merged += arr1[i:]
        merged += arr2[j:]
        return merged

    def find_kth_element(k):
        if not arr1 or k == 0:
            return arr2[k]
        if k == n:
            return arr1[n - 1]
        if k == n - 1:
            return min(arr1[n - 1], arr2[n - 1])
        if arr1[0] > arr2[n - 1]:
            return arr2[k]
        if arr2[0] > arr1[n - 1]:
            return arr1[k]
        mid1, mid2 = arr1[n // 2], arr2[n // 2]
        if mid1 > mid2:
            return find_kth_element(k - n // 2)
        if mid2 > mid1:
            return find_kth_element(k - n // 2)
        return min(mid1, mid2)

    merged = merge_sorted_lists(arr1, arr2)
    n = len(merged)
    k = n // 2
    if n % 2 == 0:
        return (merged[k] + merged[k - 1]) / 2
    else:
        return merged[k]
