def maxAverageOfPath(cost):
    n = len(cost)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][0] = cost[i][0] / (i + 1)

    for j in range(n):
        dp[0][j] = cost[0][j] / (j + 1)

    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j] + cost[i][j] / (i + j + 1), dp[i][j-1] + cost[i][j] / (i + j + 1))

    return dp[n-1][n-1]
