            return arr2[left2 + k]
        if left2 >= len(arr2):
            return arr1[left1 + k]
        if k == 0:
            return min(arr1[left1], arr2[left2])
        mid1 = (left1 + left1 + len(arr1) - 1) // 2
        mid2 = (left2 + left2 + len(arr2) - 1) // 2
        if arr1[mid1] < arr2[mid2]:
            return find_kth_helper(arr1, arr2, mid1 + 1, left2, k - (mid1 - left1 + 1))
        else:
            return find_kth_helper(arr1, arr2, left1, mid2 + 1, k - (mid2 - left2 + 1))

    if k < 0:
        return -1
    return find_kth_helper(arr1, arr2, 0, 0, k)

