def comb_sort(nums):
    def generate_shuffled(nums):
        n = len(nums)
        for i in range(n):
            yield nums[i]

    def distance(a, b):
        return abs(a - b)

    def swap(nums, i, j):
        nums[i], nums[j] = nums[j], nums[i]

    n = len(nums)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        sorted = True
        shift = int(n * shrink_factor)
        if shift < n:
            shift = n
        for i in range(0, n - shift, shift):
            if distance(nums[i], nums[i + shift]) > 1:
                swap(nums, i, i + shift)
                sorted = False

    return list(generate_shuffled(nums))

# Example usage
print(comb_sort([0.9, 0.5, 0.1, 0.8, 0.3, 0.4]))
