def is_undulating(n):
    # Convert the number to a string to easily access individual digits
    s = str(n)

    # Check if the length of the string is less than 3, which cannot be undulating
    if len(s) < 3:
        return False

    # Check if the number starts and ends with the same digit (impossible for undulating)
    if s[0] != s[-1]:
        return False

    # Check for undulating pattern: every two adjacent digits must be the same
    for i in range(1, len(s)-1, 2):
        if s[i] != s[i+1]:
            return False

    # If all checks pass, the number is undulating
    return True

