    else:
        diff = max_c - min_c
        s = diff / max_c
        if max_c == r:
            h = (g - b) / diff % 6
        elif max_c == g:
            h = (b - r) / diff + 2
        elif max_c == b:
            h = (r - g) / diff + 4
        h /= 6
    return h, s, v
