def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fib(n):
        a, b = 0, 1
        for _ in range(n):
            a, b = b, a + b
            yield a

    fib_seq = list(fib(n))
    return next(x for x in fib_seq if is_prime(x) and x > 1) if n > 0 else 0
