def extract_string(str, l):
    def extract_helper(s, length):
        # Base case: if length is 0 or negative, return an empty list
        if length <= 0:
            return []
        # Base case: if the string is empty, return an empty list
        if not s:
            return []
        # Recursive case: if the string length is less than or equal to length, return the string
        if len(s) <= length:
            return [s]
        # Recursive case: if the string length is greater than length, return the first character and the result of the rest
        else:
            return [s[:length]] + extract_helper(s[1:], length - 1)

    # Split the input string into words, then apply helper function to each word
    return [item for sublist in [extract_helper(word, l) for word in str.split()] for item in sublist]
