def find_solution(a, b, n):
    if n == 0:
        return (0, 0)

    if n < 0:
        n = -n
        a = -a
        b = -b

    if gcd(a, b) > n:
        return None

    x, y, t = 0, 1, a
    u, v, w = 1, 0, b

    while t != 0:
        q, r = divmod(n, t)
        x, y = x - q * u, y - q * v
        a, b, n = b, r, u
        u, v, w = v, w, u - q * v
        t = a

    return (x, y) if n == 0 else None

