import math

def factorize(n: int) -> List[int]:
    factors = []
    # Handle factor 2 separately
    count = 0
    while n % 2 == 0:
        n //= 2
        count += 1
    if count > 0:
        factors.append(2)
    # Check for odd factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        count = 0
        while n % i == 0:
            n //= i
            count += 1
        if count > 0:
            factors.append(i)
    # If n is a prime number greater than 2
    if n > 2:
        factors.append(n)
    return factors

