    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def fib_generator():
        a, b = 0, 1
        while True:
            yield b
            a, b = b, a + b

