def get_total_number_of_sequences(m, n):
    if m < 1 or n < 1:
        return 0

    # Initialize DP table
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0] = 1  # Base case: one way to create empty sequence

