def maxAverageOfPath(cost):
    from functools import lru_cache

    N = len(cost)

    @lru_cache(maxsize=None)
    def get_max_avg(current_x, current_y):
        if (current_x, current_y) == (N - 1, N - 1):
            return cost[current_x][current_y]
        max_avg = 0
        if current_x < N - 1:
            max_avg = max(max_avg, cost[current_x][current_y] + get_max_avg(current_x + 1, current_y))
        if current_y < N - 1:
            max_avg = max(max_avg, cost[current_x][current_y] + get_max_avg(current_x, current_y + 1))
        return max_avg / 2

    return get_max_avg(0, 0)
