def move_one_ball(arr):
    # Check if the array is already sorted in non-decreasing order
    if all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1)):
        return True

    # If not sorted, find the point where the array breaks the non-decreasing order
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            # Check if the array can be sorted by a right shift
            if arr[i + 1:] + arr[:i + 1] == sorted(arr):
                return True
            break
    return False
