import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0,1), (1,0), (-1,0), (0,-1)]
    visited = set()
    heap = [(grid[0][0], 0, 0)]  # (path_value, path_length, cell_position)
    min_path = float('inf')
    min_path_values = []

    while heap:
        path_value, path_length, cell_position = heapq.heappop(heap)
        row, col = cell_position

        if (row, col) in visited:
            continue
        visited.add((row, col))

        if path_length == k:
            if path_value < min_path:
                min_path = path_value
                min_path_values = [grid[row][col]]
            elif path_value == min_path:
                min_path_values.append(grid[row][col])
            continue

        for dr, dc in directions:
            newRow, newCol = row + dr, col + dc
            if 0 <= newRow < N and 0 <= newCol < N:
                heapq.heappush(heap, (path_value + grid[newRow][newCol], path_length + 1, (newRow, newCol)))

    return min_path_values

