def get_total_number_of_sequences(m, n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i, prev):
        if i == n:
            return 1
        count = 0
        for next_val in range(2 * prev, m + 1):
            count += dp(i + 1, next_val)
        return count

    return dp(0, 1)
