    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x, y = extended_gcd(b % a, a)
        return gcd, y - (b // a) * x, x

    gcd_ab, x_coeff, y_coeff = extended_gcd(abs(a), abs(b))

