def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if m == 0 or n < 0:
        return 0

    dp = [[0 for _ in range(n+1)] for _ in range(m+1)]
    dp[0][0] = 1

    for i in range(1, m+1):
        for j in range(n+1):
            if j == 0:
                dp[i][j] = dp[i-1][j]  # only previous element is valid
            else:
                dp[i][j] = dp[i-1][j]  # valid from previous
                if i >= 2 * j:
                    dp[i][j] += dp[i-2*j][j-1]  # valid from 2*j

    return dp[m][n]
