def find_solution(a, b, n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        s, old_s = 0, 1
        t, old_t = 1, 0
        r, old_r = y, x
        while r != 0:
            old_s, s = s, old_s - (x // y) * s
            old_t, t = t, old_t - (x // y) * t
            old_r, r = r, old_r - (x // y) * r
        return old_s, old_t

    def lcm(x, y):
        return x * y // gcd(x, y)

    def find_linear_combination(x, y, n):
        g, s, t = extended_gcd(x, y)
        if n % g != 0:
            return None
        return (n // g * s, n // g * t)

    a, b, n = abs(a), abs(b), abs(n)
    if a == 0:
