    if b == 0:
        return (0, n) if n == 0 else None

    if a > b:
        a, b = b, a

    x, y = find_linear_combination(a, b, n)
    lcm_ab = lcm(a, b)
    if x:
        return (x * (n // lcm_ab), y * (n // lcm_ab))
    else:
        return (0, n // b)
