def is_majority(arr, n, x):
    left = 0
    right = n // 2

    while right < n and arr[left] == arr[right]:
        left += 1
        right += 1

    if right == n:
        return True

    left = right
    right = n - 1

    while left < right:
        mid = (left + right) // 2
        if arr[mid] < x:
            left = mid + 1
        else:
            right = mid

    first_occurrence = left

    left = n // 2 - 1
    right = n - 1

    while left < right:
        mid = (left + right + 1) // 2
        if arr[mid] > x:
            right = mid - 1
        else:
            left = mid

    last_occurrence = left

    return last_occurrence - first_occurrence + 1 > n // 2
