def find_zero(xs: list):
    if len(xs) % 2 != 0 or max(xs) == 0:
        raise ValueError("Invalid input or no solution exists")

    # Find the first zero using the given constraints
    # xs are coefficients of a polynomial with even number of coefficients
    # largest non-zero coefficient
    # x0 = -coeffs[1] / coeffs[0]
    x0 = -xs[1] / xs[0]
    return round(x0, 2)

