def re_arrange_array(arr, n):
    # Initialize pointers for the beginning and end of the first n elements
    start, end = 0, n-1
    while start < end:
        # Ensure that the start pointer is pointing to a negative number
        while arr[start] < 0 and start < end:
            start += 1
        # Ensure that the end pointer is pointing to a positive number
        while arr[end] >= 0 and start < end:
            end -= 1
        # Swap the numbers at the start and end pointers
        if start < end:
            arr[start], arr[end] = arr[end], arr[start]
            start += 1
            end -= 1
    return arr

