def sum_Of_product(n):
    def binomial_coefficient(n, k):
        if k == 0 or k == n:
            return 1
        return binomial_coefficient(n - 1, k - 1) + binomial_coefficient(n - 1, k)

    total_sum = 0
    for k in range(1, n):
        product = binomial_coefficient(n, k) * binomial_coefficient(n, k + 1)
        total_sum += product
    return total_sum
