    shrink = 1.3  # Commonly used shrink factor
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted = is_sorted()

        if not sorted:
            for i in range(len(nums) - gap):
                if nums[i] > nums[i + gap]:
                    swap(i, i + gap)
