def find_solution(a, b, n):
    from math import gcd

    # If n is less than 0, it's impossible to find x and y as positive integers
    if n < 0:
        return None

    # Extended Euclidean Algorithm to find x and y
    def extended_gcd(x, y):
        if x == 0:
            return (y, 0, 1)
        else:
            g, y1, x1 = extended_gcd(y % x, x)
            return (g, x1 - (y // x) * y1, y1 + (x // x) * x1)

    # Calculate the gcd, if gcd does not divide n, then no solution exists
    g = gcd(a, b)
    if n % g != 0:
        return None

    # Calculate x and y using the gcd result
    g, x, y = extended_gcd(a, b)
    x = x * (n // g)
    y = y * (n // g)

    return (x, y)
