def minPath(grid, k):
    N = len(grid)
    dp = [[[float('inf')] * (k + 1) for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for step in range(k + 1):
        for i in range(N):
            for j in range(N):
                if step == 0:
                    dp[i][j][step] = grid[i][j]
                else:
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        x, y = i + dx, j + dy
                        if 0 <= x < N and 0 <= y < N:
                            dp[x][y][step] = min(dp[x][y][step], dp[i][j][step - 1] + grid[x][y])

    path = []
    i, j = N - 1, N - 1
    for step in range(k, -1, -1):
        while 0 <= i < N and 0 <= j < N and dp[i][j][step] == dp[i][j][step - 1] + grid[i][j]:
            path.append(grid[i][j])
            i, j = i - 1, j - 1
    return path[::-1]
