def remove_parenthesis(items):
    # Check if the string is empty or only contains parentheses
    if not items or items[0] == ']' or items[0] == '}' or items[0] == ')':
        return items

    # Initialize variables
    stack = []
    result = []

    for char in items:
        # If the character is an opening parenthesis, push it onto the stack
        if char in '([':
            stack.append(char)
        # If the character is a closing parenthesis
        elif char in ')]':
            # Continue until the matching opening parenthesis is found
            while stack and stack[-1] != char:
                result.append(stack.pop())
            stack.pop()  # Pop the matching opening parenthesis
        # Append non-parenthesis characters to the result
        if char not in '([':
            result.append(char)

    # Combine the stack content with the result
    while stack:
        result.append(stack.pop())

    # Join the result list into a string
    return ''.join(result)
