def count_rotation(arr):
    if not arr or len(arr) <= 1:
        return 0

    n = len(arr)
    low, high = 0, n - 1

    while low <= high:
        if arr[low] <= arr[high]:
            return low

        mid = (low + high) // 2
        next_mid = (mid + 1) % n
        prev_mid = (mid - 1 + n) % n

        if arr[prev_mid] <= arr[mid] <= arr[next_mid]:
            return mid + 1
        elif arr[low] <= arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return 0
