def find_solution(a, b, n):
    if n < 0 or gcd(a, b) > n:
        return None
    if n == 0:
        return (0, 0)

    # Extended Euclidean Algorithm to find one solution
    def extended_gcd(x, y):
        if x == 0:
            return (y, 0, 1)
        gcd, s, t = extended_gcd(y % x, x)
        return (gcd, t - (y // x) * s, s)

    _, s, t = extended_gcd(a, b)
    x0, y0 = s * (n // a), t * (n // b)

    # Check if the found solution satisfies the equation
    if a * x0 + b * y0 == n:
        return (x0, y0)

    # Find the general solution
    k = (n - a * x0) // b
    x = x0 + k * b
    y = y0 - k * a

    return (x, y)
