    # Initialize the DP array to store the maximum sum of bitonic subsequence ending at each index
    dp = arr.copy()
    dp2 = arr.copy()

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]
            if arr[i] > arr[j] and dp2[i] < dp2[j] - arr[i]:
                dp2[i] = dp2[j] - arr[i]

    # The maximum sum of bitonic subsequence is the maximum of dp[i] + dp2[i] for all i
    return max(dp[i] + dp2[i] for i in range(n))

