def sumofFactors(n):
    def factors(num):
        result = set()
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                result.add(i)
                result.add(num // i)
        return result

    even_factors = factors(n) & set(filter(lambda x: x % 2 == 0, factors(n)))
    return sum(even_factors)
