def pancake_sort(nums):
    def flip(nums, k):
        """Flip the first k elements of nums."""
        nums[:k] = reversed(nums[:k])

    n = len(nums)
    for size in range(n, 1, -1):
        # Find the index of the maximum element in nums[0:size]
        max_index = nums.index(max(nums[:size]))
        if max_index != size - 1:
            # Flip the maximum element to the front if it's not already there
            if max_index != 0:
                flip(nums, max_index + 1)
            # Flip the maximum element to the end
            flip(nums, size)
    return nums

